-- Official prerequisite graph for Engenharia da Computação (FT05), curriculum 2009/1.
-- Source: public eCampus "Grades Curriculares" report, course external id 96,
-- curriculum external id 1215. The report is generated by POST and publishes
-- the period, workload and prerequisite columns used below.

UPDATE curriculum
   SET mandatory_workload_hours = 3195,
       elective_workload_hours = 480,
       extension_workload_hours = NULL
 WHERE id = '20000000-0000-0000-0000-000000000001';

INSERT INTO discipline (
    id, code, name, workload_hours, active, source, external_id, synced_at
) VALUES
    (md5('ufam-ecampus:discipline:IEC013')::UUID, 'IEC013', 'Algoritmos e Estrutura de Dados II', 90, TRUE, 'UFAM_ECAMPUS', 'IEC013', TIMESTAMPTZ '2026-09-24 12:00:00-04'),
    (md5('ufam-ecampus:discipline:IEM141')::UUID, 'IEM141', 'Equações Diferenciais Ordinárias', 60, TRUE, 'UFAM_ECAMPUS', 'IEM141', TIMESTAMPTZ '2026-09-24 12:00:00-04')
ON CONFLICT (code) DO UPDATE SET
    name = EXCLUDED.name,
    workload_hours = EXCLUDED.workload_hours,
    active = TRUE,
    source = EXCLUDED.source,
    external_id = EXCLUDED.external_id,
    synced_at = EXCLUDED.synced_at;

UPDATE discipline
   SET workload_hours = 90,
       source = 'UFAM_ECAMPUS',
       synced_at = TIMESTAMPTZ '2026-09-24 12:00:00-04'
 WHERE code = 'FTE029';

DELETE FROM curriculum_component
 WHERE curriculum_id = '20000000-0000-0000-0000-000000000001'
   AND discipline_id = (SELECT id FROM discipline WHERE code = 'IEM708');

INSERT INTO curriculum_component (
    id, curriculum_id, discipline_id, suggested_period, component_type
)
SELECT
    md5('ft05-2009-1:component:' || discipline.code)::UUID,
    '20000000-0000-0000-0000-000000000001',
    discipline.id,
    seed.suggested_period,
    'MANDATORY'
FROM (VALUES
    ('IEC013', 3::SMALLINT),
    ('IEM141', 3::SMALLINT)
) AS seed(code, suggested_period)
JOIN discipline ON discipline.code = seed.code
ON CONFLICT (curriculum_id, discipline_id) DO UPDATE SET
    suggested_period = EXCLUDED.suggested_period,
    component_type = EXCLUDED.component_type;

-- The public eCampus report places the final project sequence in periods 9 and 10.
UPDATE curriculum_component component
   SET suggested_period = period_update.suggested_period
  FROM discipline,
       (VALUES
           ('FTL068', 9::SMALLINT),
           ('FTL069', 10::SMALLINT),
           ('FTL216', 9::SMALLINT)
       ) AS period_update(code, suggested_period)
 WHERE component.curriculum_id = '20000000-0000-0000-0000-000000000001'
   AND component.discipline_id = discipline.id
   AND discipline.code = period_update.code;

DELETE FROM discipline_prerequisite
 WHERE curriculum_id = '20000000-0000-0000-0000-000000000001';

CREATE TEMPORARY TABLE ft05_prerequisite_seed (
    discipline_code VARCHAR(32) NOT NULL,
    prerequisite_code VARCHAR(32) NOT NULL
) ON COMMIT DROP;

