INSERT INTO discipline_prerequisite (
    discipline_id, prerequisite_id, curriculum_id
)
SELECT
    discipline.id,
    prerequisite.id,
    '20000000-0000-0000-0000-000000000001'
FROM ft05_prerequisite_seed seed
JOIN discipline ON discipline.code = seed.discipline_code
JOIN discipline prerequisite ON prerequisite.code = seed.prerequisite_code
ON CONFLICT DO NOTHING;

INSERT INTO curriculum_source_snapshot (
    id,
    curriculum_id,
    source_url,
    source_title,
    source_version,
    published_at,
    captured_at,
    trust_status,
    prerequisite_data_available,
    notes
) VALUES (
    '50000000-0000-0000-0000-000000000002',
    '20000000-0000-0000-0000-000000000001',
    'https://ecampus.ufam.edu.br/ecampus/gradesCurriculares',
    'Grades Curriculares — eCampus UFAM',
    '2009/1 · curso 96 · matriz 1215',
    NULL,
    TIMESTAMPTZ '2026-09-24 12:00:00-04',
    'OFFICIAL',
    TRUE,
    'Relações de pré-requisito transcritas do relatório público da matriz 1215 gerado pelo eCampus. O diagrama do CAECom foi usado apenas como referência visual.'
) ON CONFLICT (curriculum_id, source_url, source_version) DO UPDATE SET
    source_title = EXCLUDED.source_title,
    captured_at = EXCLUDED.captured_at,
    trust_status = EXCLUDED.trust_status,
    prerequisite_data_available = EXCLUDED.prerequisite_data_available,
    notes = EXCLUDED.notes;
